import sqlite3
from contextlib import closing
from agents import function_tool as tool
DB_PATH = 'reservations.db'

@tool
def cancel_reservation(reservation_id: int, guest_phone: str) -> dict:
    if reservation_id <= 0:
        return {'ok': False, 'error': 'invalid reservation_id'}
    phone = ''.join((ch for ch in guest_phone if ch.isdigit()))
    if len(phone) < 7:
        return {'ok': False, 'error': 'invalid phone number'}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        with conn:
            row = conn.execute('SELECT id, restaurant_id, table_id, guest_name, guest_phone, party_size, start_time, status FROM reservations WHERE id = ?', (reservation_id,)).fetchone()
            if row is None:
                return {'ok': False, 'error': 'reservation not found'}
            stored = ''.join((ch for ch in row['guest_phone'] if ch.isdigit()))
            if stored[-7:] != phone[-7:]:
                return {'ok': False, 'error': 'phone number does not match'}
            conn.execute('DELETE FROM reservations WHERE id = ?', (reservation_id,))
            # Revoke any shared access and pending invites tied to this reservation
            conn.execute('DELETE FROM reservation_shares WHERE reservation_id = ?', (reservation_id,))
            conn.execute("UPDATE reservation_invites SET status = 'revoked' WHERE reservation_id = ? AND status = 'pending'", (reservation_id,))
            return {'ok': True, 'cancelled': dict(row)}
